import{_ as t,o,c as a,a3 as i}from"./chunks/framework.cNy3aYYk.js";const u=JSON.parse('{"title":"Kelviq Central Gateway — Production Readiness","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Kelviq Central Gateway — Production Readiness | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/kelviq-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Kelviq Central Gateway — Production Readiness | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/kelviq-production-readiness"}]]},"headers":[],"relativePath":"deployment/kelviq-production-readiness.md","filePath":"deployment/kelviq-production-readiness.md","lastUpdated":1794259478000}'),d={name:"deployment/kelviq-production-readiness.md"};function n(r,e,c,l,s,p){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="kelviq-central-gateway-—-production-readiness" tabindex="-1">Kelviq Central Gateway — Production Readiness <a class="header-anchor" href="#kelviq-central-gateway-—-production-readiness" aria-label="Permalink to &quot;Kelviq Central Gateway — Production Readiness&quot;">​</a></h1><p>Audit date: <strong>2026-11-07</strong>. Scope: Central Marketplace billing via Kelviq (sandbox → live). Tenant-owned Kelviq keys for customer invoices remain out of scope.</p><h2 id="verdict" tabindex="-1">Verdict <a class="header-anchor" href="#verdict" aria-label="Permalink to &quot;Verdict&quot;">​</a></h2><p><strong>Ready for sandbox rollout.</strong> Live default is unblocked after the hardening in this delivery (timestamp replay window, <code>invoice.paid</code> renewals, pause/resume entitlement sync, API mapping validation, sanitized checkout errors).</p><h2 id="evidence" tabindex="-1">Evidence <a class="header-anchor" href="#evidence" aria-label="Permalink to &quot;Evidence&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Check</th><th>Result</th></tr></thead><tbody><tr><td>Headed Playwright (one admin session)</td><td><code>billing.payment-gateways.kelviq.headed.spec.ts</code> — 5/5</td></tr><tr><td>Billing dashboard e2e (incl. Kelviq configure)</td><td><code>billing.dashboard.spec.ts</code> — pass</td></tr><tr><td>Pest</td><td><code>KelviqGatewayTest</code>, <code>KelviqWebhookTest</code>, isolation, management</td></tr><tr><td>Secrets</td><td>Encrypted <code>payment_gateways.config</code>; redacted API; env fallbacks sandbox-off by default</td></tr><tr><td>Webhook verify</td><td>HMAC <code>id.timestamp.body</code> + <strong>±300s</strong> timestamp tolerance</td></tr><tr><td>Idempotency</td><td><code>webhook_logs.provider_event_id</code></td></tr></tbody></table><h2 id="hardening-shipped-from-audit" tabindex="-1">Hardening shipped from audit <a class="header-anchor" href="#hardening-shipped-from-audit" aria-label="Permalink to &quot;Hardening shipped from audit&quot;">​</a></h2><ol><li>Webhook timestamp replay rejection (<code>KelviqWebhookVerifier</code>, 300s).</li><li><code>invoice.paid</code> → <code>payment_succeeded</code> (renewals).</li><li><code>subscription.paused</code> → local <code>suspended</code> + entitlement forget; resume restores <code>active</code>.</li><li>API <code>PUT …/module-prices</code> rejects numeric Kelviq plan identifiers.</li><li>Checkout failures no longer echo raw Kelviq API messages to clients.</li><li><code>KELVIQ_ENV=live</code> aliases <code>production</code> for seeder mode.</li></ol><h2 id="remaining-ops-not-code-blockers" tabindex="-1">Remaining ops (not code blockers) <a class="header-anchor" href="#remaining-ops-not-code-blockers" aria-label="Permalink to &quot;Remaining ops (not code blockers)&quot;">​</a></h2><ol><li>Paste sandbox keys; seed gateways; map published plan identifiers.</li><li>Register webhook events including <strong><code>invoice.paid</code></strong> plus: <code>checkout.completed</code>, <code>invoice.payment_failed</code>, <code>subscription.created</code>, <code>subscription.updated</code>, <code>subscription.plan_changed</code>, <code>subscription.paused</code>, <code>subscription.resumed</code>, <code>subscription.cancelled</code>.</li><li>Real sandbox purchase + renewal with forwarded webhooks.</li><li>Business verification / payouts → production plans → <code>KELVIQ_ENV=production</code> + live keys → production webhook → set Kelviq default.</li></ol><h2 id="portal-note" tabindex="-1">Portal note <a class="header-anchor" href="#portal-note" aria-label="Permalink to &quot;Portal note&quot;">​</a></h2><p><code>KelviqGateway::createPortalSession()</code> is implemented for parity with Creem; Central UI does not yet expose “Manage billing”. Treat as follow-up, not a Marketplace checkout blocker.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/developer-guide/kelviq">Kelviq gateway</a></li><li><a href="/deployment/payment-gateways">Payment gateways production</a></li><li><a href="/changelog/">CHANGELOG</a></li></ul>',14)])])}const h=t(d,[["render",n]]);export{u as __pageData,h as default};
